                const char *err_primaries = "ERR Please use SETSLOT only with primaries.";
                const char *err_unblocked = "UNBLOCKED";
                int ignore = 0;
                ignore += !strncmp(*err, err_masters, strlen(err_masters));
                ignore += !strncmp(*err, err_primaries, strlen(err_primaries));
                ignore += !strncmp(*err, err_unblocked, strlen(err_unblocked));
